const LinterMessage = require('./message')
const { PROTECTED_NAMESPACES, isBuiltIn } = require('./config')

const EXTENSION_ALLOWLIST = 'extension-allowlist'

function _protectedNamespaceOf(name) {
  if (!name) return null
  return PROTECTED_NAMESPACES.find(ns => name === ns || name.startsWith(`${ns}.`)) ?? null
}

// Collects all names explicitly listed in the extension-allowlist, so they are
// allowed even if they fall into a protected namespace.
function _allowlistedNames(mtxConfig) {
  const names = new Set()
  for (const permission of mtxConfig?.[EXTENSION_ALLOWLIST] ?? []) {
    for (const name of permission.for ?? []) names.add(name)
  }
  return names
}

function locationString(element) {
  const loc = element?.$location
  if (!loc) return ''
  const line = loc.line ? `${loc.line}:` : ''
  return loc.col ? `${loc.file}:${line}${loc.col}:` : `${loc.file}:${line}`
}

// Collects all source targets (fully-qualified names) referenced in a query's
// `from` clause, recursing into joins (`from.args`) and sub-queries
// (`from.SELECT` / `from.SET.args`).
function _collectFromTargets(from, acc = []) {
  if (!from || typeof from !== 'object') return acc

  if (Array.isArray(from.ref) && from.ref.length) {
    const seg = from.ref[0]
    const name = typeof seg === 'string' ? seg : seg?.id
    if (name) acc.push(name)
  }

  // joins: from.args is an array of froms
  if (Array.isArray(from.args)) {
    for (const arg of from.args) _collectFromTargets(arg, acc)
  }

  // sub-query: from.SELECT is itself a query body with its own from
  if (from.SELECT) _collectFromTargets(from.SELECT.from, acc)

  // set operation sub-query: from.SET.args is an array of query bodies
  if (from.SET && Array.isArray(from.SET.args)) {
    for (const arg of from.SET.args) _collectFromTargets(arg.SELECT?.from, acc)
  }

  return acc
}

// Rejects defining, extending or annotating artifacts in a protected namespace (e.g. 'cds.xt'),
// as well as projections/views that read from an artifact in a protected namespace.
// Runs unconditionally, independent of linter configuration.
module.exports = class ProtectedNamespaceChecker {

  // eslint-disable-next-line no-unused-vars
  check(reflectedCsn, fullCsn, compileDir, mtxConfig) {
    const messages = []
    const allowlisted = _allowlistedNames(mtxConfig)

    for (const name of Object.keys(reflectedCsn.definitions ?? {})) {
      const def = reflectedCsn.definitions[name]

      // name in a protected namespace (built-ins + allowlisted names excluded)
      if (!isBuiltIn(name) && !allowlisted.has(name) && _protectedNamespaceOf(name)) {
        messages.push(this._createWarning(name, def))
        continue // avoid double-counting: name-based block already fired
      }

      // projection/view reading from a protected artifact (allowlist override only, no isBuiltIn)
      const queryBody = def.query?.SELECT ?? def.projection
      if (queryBody) {
        for (const target of _collectFromTargets(queryBody.from)) {
          if (!allowlisted.has(target) && _protectedNamespaceOf(target)) {
            messages.push(this._createExpositionWarning(target, def))
          }
        }
      }
    }

    for (const extension of reflectedCsn.extensions ?? []) {
      const target = extension.extend ?? extension.annotate
      if (!allowlisted.has(target) && _protectedNamespaceOf(target)) {
        messages.push(this._createWarning(target, extension))
      }
    }

    return messages
  }

  _createWarning(name, element) {
    const namespace = _protectedNamespaceOf(name)
    const message = `Extending, annotating or defining '${name}' in the protected namespace '${namespace}' is not supported in extensions`
    return new LinterMessage(locationString(element) + message, element)
  }

  _createExpositionWarning(name, element) {
    const namespace = _protectedNamespaceOf(name)
    const message = `Exposing '${name}' from the protected namespace '${namespace}' via a projection/view is not supported in extensions`
    return new LinterMessage(locationString(element) + message, element)
  }
}
